function buildSources(p) {
  return {
    taxonomy: src(...(p.taxonomySource || ["GBIF Backbone Taxonomy", `https://api.gbif.org/v1/species/${p.gbif}`])),
    conservation: src(...(p.conservationSource || ["IUCN Red List category linked through GBIF", `https://api.gbif.org/v1/species/${p.gbif}/iucnRedListCategory`])),
    general: src(...p.general),
    ecology: src(...(p.ecologySource || p.general)),
    range: src(...p.range),
  };
}

function buildRecord(p) {
  const [statusEn, statusZh] = labels[p.status];
  const hasPolygons = p.polygons.length > 0;
  const statusNote = p.status === "NE"
    ? b("No species-level global IUCN assessment was confirmed. Not Evaluated means assessment is absent, not that the species is secure.", "未确认到物种级IUCN全球评估。未评估表示缺少评估，并不表示该物种安全。")
    : b(`The species-level global category checked on ${CHECKED} is ${statusEn}; regional and legal listings may differ.`, `已于${CHECKED}核对物种级全球等级为${statusZh}；地区和法律名录可能不同。`);
  return {
    content_version: 2,
    content_review: REVIEWED ? {
      factual_qc: "source-checked", bilingual_qc: "line-by-line-reviewed", reviewed_at: CHECKED,
      reviewer: "Codex exact-taxon source, bilingual, range and image-risk audit",
      notes: "Every English and Chinese section was compared line by line. Accepted species identity, IUCN scope, numeric claims, map generalization and look-alike image risks were checked against the cited sources. Generalized polygons do not imply continuous occupancy.",
    } : { factual_qc: "pending", bilingual_qc: "pending" },
    id: p.id, name_zh: p.nameZh, name_en: p.nameEn, scientific_name: p.scientific, ui_tags: p.tags,
    taxonomy: p.taxonomy,
    conservation_status: { code: p.status, en: statusEn, zh: statusZh, note_en: statusNote.en, note_zh: statusNote.zh },
    description: p.summary,
    encyclopedia: {
      anatomy: sourced(p.anatomy.en, p.anatomy.zh),
      ecology_and_behavior: sourced(p.ecology.en, p.ecology.zh, ["general", "ecology"]),
      habitat_and_distribution: sourced(p.rangeText.en, p.rangeText.zh, ["range"]),
    },
    rich_content: {
      quick_facts: p.facts,
      life_cycle_and_reproduction: sourced(p.life.en, p.life.zh, ["general", "ecology"]),
      adaptations: p.adaptations,
      ecological_role: sourced(p.role.en, p.role.zh, ["ecology"]),
      conservation_and_threats: { population_trend: p.trend, threats: p.threats, actions: p.actions, source_keys: ["conservation", "general", "range"] },
      identification: { key_features: p.identify, similar_species: p.similar, source_keys: ["general", "taxonomy", "range"] },
      communication_and_senses: sourced(p.senses.en, p.senses.zh, ["general", "ecology"]),
      seasonal_calendar: sourced(p.seasonal.en, p.seasonal.zh, ["general", "ecology", "range"]),
      relationship_with_humans: sourced(p.humans.en, p.humans.zh, ["general", "conservation"]),
      evolution: sourced(`${p.nameEn} belongs to genus ${p.taxonomy.genus.en}, family ${p.taxonomy.family.en}, order ${p.taxonomy.order.en}. This record uses the accepted species-level binomial ${p.scientific}; facts and images are not transferred from close relatives.`, `${p.nameZh}归入${p.taxonomy.genus.zh}、${p.taxonomy.family.zh}、${p.taxonomy.order.zh}。本条目采用接受的物种级二名法${p.scientific}；不会从近缘种移用事实或图片。`, ["taxonomy"]),
      field_signs: sourced(p.field.en, p.field.zh, ["general", "ecology"]),
      did_you_know: p.trivia,
      class_specific: [p.classModule],
    },
    habitat: {
      text_en: p.rangeText.en, text_zh: p.rangeText.zh,
      map_coordinates: p.map, map_zoom_level: p.zoom, global_distribution_polygons: p.polygons,
      range_review: {
        display_mode: hasPolygons ? "verified-polygon" : "representative-point",
        previous_result: "not-applicable", source_keys: ["range"],
        comparison_en: hasPolygons
          ? "This new record has no previous geometry. The displayed nonrectangular polygons conservatively generalize the cited institutional distribution evidence for readable map display; boundaries are approximate and never imply continuous occupancy."
          : "This new record has no previous geometry. A representative point is used because the habitat is spatially discontinuous or three-dimensional and a filled polygon would imply unsupported continuous occupancy.",
        comparison_zh: hasPolygons
          ? "这是没有旧几何的新记录。显示的非矩形多边形依据所引机构分布证据作保守概化，以便地图清晰呈现；边界为近似范围，绝不表示圈内连续分布。"
          : "这是没有旧几何的新记录。由于生境在空间上不连续或具有三维深度，填色多边形会错误暗示连续占据，故使用代表点。",
        checked_at: CHECKED,
      },
    },
    image: null,
    sources: buildSources(p),
  };
}

const activeProfiles = profiles
  .filter((profile) => !["vampire-squid", "barreleye", "yeti-crab"].includes(profile.id))
  .concat(replacementProfiles);
if (activeProfiles.length !== 10) throw new Error(`Expected 10 active profiles, found ${activeProfiles.length}`);
const ids = new Set(activeProfiles.map((profile) => profile.id));
if (ids.size !== activeProfiles.length) throw new Error("Duplicate IDs in batch");
const onlyIndex = process.argv.indexOf("--only");
const requestedOnly = onlyIndex >= 0 ? process.argv[onlyIndex + 1] : null;
const requestedIds = requestedOnly ? new Set(requestedOnly.split(",").filter(Boolean)) : null;
const selectedProfiles = requestedIds ? activeProfiles.filter((profile) => requestedIds.has(profile.id)) : activeProfiles;
if (requestedIds && selectedProfiles.length !== requestedIds.size) throw new Error(`Unknown --only profile list: ${requestedOnly}`);
const records = selectedProfiles.map(buildRecord);
fs.writeFileSync(OUT, `${JSON.stringify(records, null, 2)}\n`);
process.stdout.write(`Wrote ${records.length} ${REVIEWED ? "reviewed" : "pending"} records to ${OUT}\n`);
